CREATE TABLE "wechat_notification_inbox" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "wechat_notification_inbox_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"channel" text DEFAULT 'wechat' NOT NULL,
	"mchid" text NOT NULL,
	"event_id" text NOT NULL,
	"event_type" text NOT NULL,
	"content_hash" text NOT NULL,
	"decrypted_resource" text NOT NULL,
	"state" text DEFAULT 'received' NOT NULL,
	"attempts" integer DEFAULT 0 NOT NULL,
	"signature_serial" text NOT NULL,
	"received_at" timestamp with time zone DEFAULT now() NOT NULL
);
